    my = [h[0] for h in history]

    total_c = 0
    for a in opp:
        if a == 'C':
            total_c += 1
    total_d = n - total_c

    # Trailing streak of opponent actions.
    last = opp[-1]
    streak = 0
    for a in reversed(opp):
        if a == last:
            streak += 1
        else:
            break

    # Recent window stats (last 12 rounds).
    w = 12 if n >= 12 else n
    recent = opp[n - w:]
    rc = 0
    for a in recent:
        if a == 'C':
            rc += 1
    rd = w - rc

    remaining = 100 - n

    # Detect a highly exploitable always/nearly-always cooperator.
    if total_d == 0:
        if remaining <= 2:
            return 'D'
        # Defect occasionally to harvest while keeping them cooperating.
        if n % 5 == 0:
            return 'D'
        return 'C'
